update micro_steps set kind='explanation',title='Agent 先看，再决定，再行动',content='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Agent（智能体）会依据收到的信息决定下一步行动，再看行动带来的结果。以找航班为例：看到出行需求 → 决定查航班 → 得到查询结果 → 再决定是否换条件。"}]},{"type":"paragraph","content":[{"type":"text","text":"环境","marks":[{"type":"bold"}]},{"type":"text","text":"（"},{"type":"text","text":"Environment","marks":[{"type":"bold"}]},{"type":"text","text":"）是它交互的外部世界，例如航班数据库或用户。Agent 得到的只是观察，例如查询返回的几个航班，并非整个"},{"type":"text","text":"环境","marks":[{"type":"bold"}]},{"type":"text","text":"。以上为教材场景的教学改编。"}]}]}',interaction=null,success_feedback='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"观察是从"},{"type":"text","text":"环境","marks":[{"type":"bold"}]},{"type":"text","text":"取得的信息，不是整个"},{"type":"text","text":"环境","marks":[{"type":"bold"}]},{"type":"text","text":"。决定查询也不等于已经查完。"}]}]}',retry_feedback=null where id='aiad-l1-a02-s2' and unit_id='aiad-l1-a02-unit' and position=1;
end if;
