update micro_steps set kind='explanation',title='谁把这些角色连起来？',content='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"是谁把“查过什么”变成下一次决策能用的信息？运行层（Runtime）负责支撑任务运行。教材用 "},{"type":"text","text":"Harness","marks":[{"type":"bold"}]},{"type":"text","text":" 指 Agent 内环绕"},{"type":"text","text":"模型","marks":[{"type":"bold"}]},{"type":"text","text":"的运行与治理层；它还负责权限、验证和纠正。“治理”在这里只是控制和检查操作。"}]},{"type":"paragraph","content":[{"type":"text","text":"任务状态","marks":[{"type":"bold"}]},{"type":"text","text":"（"},{"type":"text","text":"State","marks":[{"type":"bold"}]},{"type":"text","text":"）记录进行到哪了，例如“已查询，等待用户选日期”。下面只展开 "},{"type":"text","text":"Harness","marks":[{"type":"bold"}]},{"type":"text","text":" 的信息组织职责：单步看任务记录怎样成为本次"},{"type":"text","text":"上下文","marks":[{"type":"bold"}]},{"type":"text","text":"，再交给"},{"type":"text","text":"模型","marks":[{"type":"bold"}]},{"type":"text","text":"。"},{"type":"text","text":"Harness","marks":[{"type":"bold"}]},{"type":"text","text":" 不是第二个决策"},{"type":"text","text":"模型","marks":[{"type":"bold"}]},{"type":"text","text":"。"}]}]}',interaction='{"mode":"explore","type":"flow-execution","edges":[{"id":"read","to":"harness","from":"state","label":"读取任务进展"},{"id":"compose","to":"context","from":"harness","label":"选取决策所需信息"},{"id":"decide","to":"model","from":"context","label":"交给模型"}],"nodes":[{"x":0,"y":0,"id":"state","label":"任务状态 State"},{"x":190,"y":0,"id":"harness","label":"Harness：组织信息"},{"x":0,"y":120,"id":"context","label":"本次上下文 Context"},{"x":190,"y":120,"id":"model","label":"Model：决定下一步"}],"events":[{"title":"1 · 任务记录","nodeId":"state","message":"已查询航班，等待用户选日期。","explanation":"State 记录任务进展；它不是外部数据库中的订单。"},{"title":"2 · 运行层读取进展","edgeId":"read","nodeId":"harness","message":"Harness 取出仍需用户选择的日期信息。","explanation":"运行与信息组织由这一层承担，不是模型凭空知道进度。"},{"title":"3 · 组织本次信息","edgeId":"compose","nodeId":"context","message":"上下文包含出行需求、查询结果和“日期待选”。","explanation":"这里只送入这次决定需要的内容，不等于整个任务记录或整个数据库。"},{"title":"4 · 模型作决定","edgeId":"decide","nodeId":"model","message":"根据收到的信息，决定请用户选择日期。","explanation":"Harness 组织信息；Model 决策。角色不同，共同支持同一个任务。"}],"teaching":{"explanation":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"任务状态","marks":[{"type":"bold"}]},{"type":"text","text":"由运行层维护；"},{"type":"text","text":"Harness","marks":[{"type":"bold"}]},{"type":"text","text":" 挑出决策需要的信息组织成"},{"type":"text","text":"上下文","marks":[{"type":"bold"}]},{"type":"text","text":"，"},{"type":"text","text":"模型","marks":[{"type":"bold"}]},{"type":"text","text":"据此决定。图展示一次信息交接，不表示所有 "},{"type":"text","text":"State","marks":[{"type":"bold"}]},{"type":"text","text":" 都必须原样发给"},{"type":"text","text":"模型","marks":[{"type":"bold"}]},{"type":"text","text":"，也没有把外部航班数据库放进 Agent。"}]}]}},"correctEdgeIds":["read","compose","decide"],"initialEdgeIds":["read","compose","decide"]}'::jsonb,success_feedback='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"State","marks":[{"type":"bold"}]},{"type":"text","text":" 记录进展；"},{"type":"text","text":"Harness","marks":[{"type":"bold"}]},{"type":"text","text":" 准备信息；"},{"type":"text","text":"Model","marks":[{"type":"bold"}]},{"type":"text","text":" 根据本次"},{"type":"text","text":"上下文","marks":[{"type":"bold"}]},{"type":"text","text":"决定。"}]}]}',retry_feedback=null where id='aiad-l1-a02-s4' and unit_id='aiad-l1-a02-unit' and position=3;
