update micro_steps set kind='interaction',title='先列任务，再列权限',content='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"教学改编：任务是“读取指定报告并在页面内总结”。需要读那份报告；删除原报告、读取无关私有文件或发邮件都不是当前任务要求。"}]},{"type":"paragraph","content":[{"type":"text","text":"按这个任务把权限分为“"},{"type":"text","text":"任务所需","marks":[{"type":"bold"}]},{"type":"text","text":"”和“"},{"type":"text","text":"额外权限","marks":[{"type":"bold"}]},{"type":"text","text":"”，直观看到权限边界。若任务改成保存草稿，就需要重新判断写入能力；"},{"type":"text","text":"最小权限","marks":[{"type":"bold"}]},{"type":"text","text":"不是永远只读。"}]}]}',interaction='{"type":"categorize","items":[{"id":"read","label":"读取指定报告"},{"id":"delete","label":"删除原报告"},{"id":"private","label":"读取无关私有文件"},{"id":"email","label":"把报告发送到外部邮箱"}],"categories":["任务所需","额外权限"],"correctCategories":["任务所需","额外权限","额外权限","额外权限"]}'::jsonb,success_feedback='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"读取指定报告支撑当前总结任务；删除、无关文件和邮件权限扩大了可影响范围，却没有帮助完成已授权任务。"}]}]}',retry_feedback='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"先固定任务：只读指定报告并在页面总结。逐张问“没有这项权限，还能完成任务吗？”删除、无关文件和外发邮件都不必要。"}]}]}' where id='aiad-l1-s03-s2' and unit_id='aiad-l1-s03-unit' and position=1;
end if;
